package site.federicotaranu.nova;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.view.accessibility.*;import org.json.*;import java.util.*;
public class ParityFinal extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void shot(String name)throws Exception{Thread.sleep(1800);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();java.io.FileOutputStream o=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),name));b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,o);o.close();}
 boolean click(AccessibilityNodeInfo n,String text){if(n==null)return false;CharSequence t=n.getText();if(t!=null&&t.toString().equalsIgnoreCase(text)){while(n!=null&&!n.isClickable())n=n.getParent();return n!=null&&n.performAction(AccessibilityNodeInfo.ACTION_CLICK);}for(int i=0;i<n.getChildCount();i++)if(click(n.getChild(i),text))return true;return false;}
 String tree(AccessibilityNodeInfo n){if(n==null)return "";String s="["+n.getClassName()+":"+n.getText()+":"+n.getContentDescription()+"]";for(int i=0;i<n.getChildCount();i++)s+=tree(n.getChild(i));return s;}
 String logic(Context c)throws Exception{long now=System.currentTimeMillis();if(WidgetData.slots(c,now,1).size()!=1)throw new Exception("lesson fixture missing");if(WidgetData.homework(c,WidgetData.homeworkTarget(now)).size()!=1)throw new Exception("homework target missing");Notifications.timer(c,now+600000);if(!c.getSharedPreferences("nova.alarms",0).contains("timer"))throw new Exception("timer not stored");Notifications.timer(c,0);if(c.getSharedPreferences("nova.alarms",0).contains("timer"))throw new Exception("timer not cancelled");for(String date:new String[]{"2026-10-23","2026-10-24","2026-10-25"}){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd");f.setTimeZone(WidgetData.ZONE);if(!WidgetData.date(WidgetData.homeworkTarget(f.parse(date).getTime())).equals("2026-10-26"))throw new Exception("weekend target "+date);}return "PASS slots,homework-weekend,timer-cancel";}
 String bridge(MainActivity a)throws Exception{String[] out={null};java.util.concurrent.CountDownLatch l=new java.util.concurrent.CountDownLatch(1);runOnMainSync(()->a.web.evaluateJavascript("(()=>{window.__parityBridge=null;(async()=>{const x=await nat('groq','set',{key:'invalid-synthetic'});const y=await nat('classeviva','login',{uid:'',pass:''});window.__parityBridge={ai:x.err,school:y.err}})();return true})()",x->{}));for(int i=0;i<30;i++){java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(1);runOnMainSync(()->a.web.evaluateJavascript("JSON.stringify(window.__parityBridge)",x->{out[0]=x;done.countDown();}));done.await(3,java.util.concurrent.TimeUnit.SECONDS);if(out[0]!=null&&out[0].contains("formato")&&out[0].contains("dati"))return out[0];Thread.sleep(1000);}throw new Exception("native callbacks "+out[0]);}
 public void onStart(){Bundle r=new Bundle();try{Context c=getTargetContext();MainActivity a=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(12000);
 r.putString("bridge",bridge(a));Calendar now=WidgetData.calendar(System.currentTimeMillis());String d=String.format(Locale.ROOT,"%04d-%02d-%02d",now.get(1),now.get(2)+1,now.get(5));int m=now.get(11)*60+now.get(12);
 NovaWidgetStore.saveTimetable(c,new JSONObject().put("lessons",new JSONArray().put(new JSONObject().put("d",now.get(7)).put("s",Math.max(0,m-5)).put("e",Math.min(1440,m+50)).put("n","Informatica").put("r","A34"))).toString());
 NovaWidgetStore.saveHomework(c,new JSONObject().put("items",new JSONArray().put(new JSONObject().put("d",WidgetData.date(WidgetData.homeworkTarget(System.currentTimeMillis()))).put("s","INFO").put("t","Esercizio sintetico di prova"))).toString());
 NovaWidgetStore.saveEvents(c,new JSONObject().put("dots",new JSONArray().put(new JSONObject().put("d",d).put("k","test"))).toString());
 AppWidgetManager am=AppWidgetManager.getInstance(c);r.putString("providers",am.getInstalledProviders().toString());r.putString("logic",logic(c));r.putBoolean("pinSupported",am.isRequestPinAppWidgetSupported());
 for(String p:new String[]{"OrarioWidget","OggiWidget","FineWidget","CompitiWidget","CalendarWidget"}){runOnMainSync(()->a.startActivity(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));Thread.sleep(1000);boolean ok=am.requestPinAppWidget(new ComponentName(c,"site.federicotaranu.nova."+p),null,null);r.putBoolean(p+"Requested",ok);Thread.sleep(2200);r.putString(p+"Dialog",tree(getUiAutomation().getRootInActiveWindow()));shot(p+"-dialog.png");boolean clicked=click(getUiAutomation().getRootInActiveWindow(),"Add to home screen")||click(getUiAutomation().getRootInActiveWindow(),"Add automatically")||click(getUiAutomation().getRootInActiveWindow(),"Add");r.putBoolean(p+"Added",clicked);Thread.sleep(2500);NovaWidget.refresh(c);c.startActivity(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1800);r.putString(p+"Home",tree(getUiAutomation().getRootInActiveWindow()));shot(p+"-home.png");r.putInt(p+"Count",am.getAppWidgetIds(new ComponentName(c,"site.federicotaranu.nova."+p)).length);}
 if(r.getInt("OrarioWidgetCount")<1||r.getInt("OggiWidgetCount")<1||r.getInt("FineWidgetCount")<1||r.getInt("CompitiWidgetCount")<1||r.getInt("CalendarWidgetCount")<1)throw new Exception("not all widgets bound");finish(Activity.RESULT_OK,r);
 }catch(Exception e){r.putString("error",e.toString());finish(Activity.RESULT_CANCELED,r);}}
}
